def find_path(graph, start, goal):
    """
    This function takes a graph (as a dictionary) and the start and goal nodes
    and returns a list of nodes that make up the path from start to goal (inclusive),
    or None if goal is unreachable.
    """
    if start == goal:
        return [start]

    # Initialize the stack with a tuple (path, current node)
    stack = [(list(), start)]
    visited = set()

    while stack:
        (path, current) = stack.pop()
        if current not in visited:
            visited.add(current)
            if current == goal:
                return path + [current]
            for next_node in graph[current]:
                if next_node not in visited:
                    stack.append((path + [current], next_node))
    return None
